import{_ as o}from"./chunks/mcp_setup_window.Bmk85iqH.js";import{_ as a,C as n,o as i,c as r,E as s,a2 as l}from"./chunks/framework.BEADHO7-.js";const f=JSON.parse('{"title":"Let AI Build the Effect","description":"An MCP server that lets AI clients such as Claude and Codex look up how Mug Typography and its Lua scripting API work, and write a script and check that it works","frontmatter":{"title":"Let AI Build the Effect","description":"An MCP server that lets AI clients such as Claude and Codex look up how Mug Typography and its Lua scripting API work, and write a script and check that it works","pageClass":"feature-guide","aside":false,"head":[["link",{"rel":"canonical","href":"https://mug-lab-3.github.io/mug-typography-docs/en/features/feature-mcp.html"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"Mug Typography Manual"}],["meta",{"property":"og:locale","content":"en_US"}],["meta",{"property":"og:title","content":"Let AI Build the Effect | Mug Typography Manual"}],["meta",{"property":"og:description","content":"An MCP server that lets AI clients such as Claude and Codex look up how Mug Typography and its Lua scripting API work, and write a script and check that it works"}],["meta",{"property":"og:url","content":"https://mug-lab-3.github.io/mug-typography-docs/en/features/feature-mcp.html"}],["meta",{"property":"og:image","content":"https://mug-lab-3.github.io/mug-typography-docs/image/social-card.png"}],["meta",{"property":"og:image:type","content":"image/png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:image:alt","content":"Mug Typography Online Manual"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:site","content":"@MugLab3"}],["meta",{"name":"twitter:title","content":"Let AI Build the Effect | Mug Typography Manual"}],["meta",{"name":"twitter:description","content":"An MCP server that lets AI clients such as Claude and Codex look up how Mug Typography and its Lua scripting API work, and write a script and check that it works"}],["meta",{"name":"twitter:image","content":"https://mug-lab-3.github.io/mug-typography-docs/image/social-card.png"}],["meta",{"name":"twitter:image:alt","content":"Mug Typography Online Manual"}]]},"headers":[],"relativePath":"en/features/feature-mcp.md","filePath":"en/features/feature-mcp.md"}'),h={name:"en/features/feature-mcp.md"};function c(p,e,g,u,d,m){const t=n("FeatureHero");return i(),r("div",null,[s(t,{language:"en",eyebrow:"MUG TYPOGRAPHY MCP",title:"Let AI Build the Effect",description:"AI clients such as Claude and Codex look up how Mug Typography and its Lua scripting API work, and write a script and check that it works. You no longer paste the reference in, and you run into broken code less often.",image:"/image/mcp_hero_en.svg","image-alt":"A diagram: the AI client looks up the spec through Mug Typography MCP, checks the script, and puts the effect into DaVinci Resolve","detail-link":"/en/features/feature-scripting","detail-label":"Lua Scripting Guide","point-one":"The AI looks things up itself","point-two":"Checks the script it writes","point-three":"Six AI clients supported","is-new":!0}),e[0]||(e[0]=l('<h2 id="how-to-use" tabindex="-1">How to Use <a class="header-anchor" href="#how-to-use" aria-label="Permalink to &quot;How to Use&quot;">​</a></h2><ol><li><p>Download the installer for your OS from the same <a href="https://muglab3.booth.pm/items/8339678" target="_blank" rel="noreferrer">BOOTH page</a> as the plugin, and run it.</p><ul><li>Windows: <code>MugTypographyMCP-Setup.exe</code></li><li>macOS: <code>MugTypographyMCP.pkg</code></li></ul><p>When it finishes, it registers itself with the AI clients it finds.</p></li><li><p>Your OS may show a security warning when you open the installer. If it does, continue like this.</p><ul><li><strong>Windows</strong>: If you see &quot;Windows protected your PC&quot;, click <strong>More info</strong>, then the <strong>Run anyway</strong> button that appears.</li><li><strong>macOS</strong>: If macOS says it cannot verify the package, close the message and open &quot;System Settings &gt; Privacy &amp; Security&quot;. Scroll down and click <strong>Open Anyway</strong> next to <code>MugTypographyMCP.pkg</code>. Control-clicking the package and choosing <strong>Open</strong> also works.</li></ul></li><li><p>Restart the AI client, or reload its MCP servers.</p></li><li><p>Ask the AI for the effect you want.</p><blockquote><p>Make a Mug Typography effect where the letters of &quot;HELLO&quot; drop in one by one from above, and add it to the current timeline.</p></blockquote></li></ol><h2 id="what-it-does" tabindex="-1">What It Does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What It Does&quot;">​</a></h2><p>With <strong>Mug Typography MCP</strong> installed, an AI client can look up what it needs about Mug Typography by itself and check the script it wrote.</p><ul><li><strong>Looks things up</strong>: the AI reads the plugin&#39;s features, the Inspector parameters, the Lua scripting API and the bundled samples whenever it needs them. You do not have to paste the reference in every time.</li><li><strong>Resolves font names</strong>: it tells the AI which fonts the plugin offers, so a font can be chosen by its display name.</li><li><strong>Checks the script it wrote</strong>: it runs the Lua script the AI wrote in the simulator and checks for errors, characters that leave the screen and changes in values. It also makes a one-frame preview image.</li></ul><p>The preview image is only a guide to placement. Always check the result in DaVinci Resolve.</p><h2 id="about-operating-davinci-resolve" tabindex="-1">About Operating DaVinci Resolve <a class="header-anchor" href="#about-operating-davinci-resolve" aria-label="Permalink to &quot;About Operating DaVinci Resolve&quot;">​</a></h2><p>Mug Typography MCP does not operate DaVinci Resolve itself. If you also want the AI to add the nodes and set the <strong>Script Text</strong>, combine it with a DaVinci Resolve MCP in the AI client. If you only want a script, you do not need the Resolve MCP.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>Windows 11 (64-bit), or macOS 13.3 or later (Apple Silicon only)</li><li>DaVinci Resolve Studio 21.1 or later with Mug Typography installed</li><li>One of these AI clients: Claude Desktop, Codex, Cursor, VS Code (GitHub Copilot), Gemini CLI, Antigravity</li></ul><h2 id="checking-and-removing-the-registration" tabindex="-1">Checking and Removing the Registration <a class="header-anchor" href="#checking-and-removing-the-registration" aria-label="Permalink to &quot;Checking and Removing the Registration&quot;">​</a></h2><p><img src="'+o+'" alt="The Mug Typography MCP window, showing all six AI clients it found as registered"></p><p>You can check the registration in this window:</p><ul><li>Windows: &quot;Mug Typography MCP&quot; in the Start menu</li><li>macOS: <code>MugTypographyMCP</code> in <code>~/Applications</code></li></ul><p>The window shows the status of each AI client it found. <strong>Register all</strong> registers every client at once, and <strong>Unregister all</strong> removes them all. <strong>Check the connection</strong> calls every tool once and shows what the AI sends and what comes back.</p><h2 id="updating-and-uninstalling" tabindex="-1">Updating and Uninstalling <a class="header-anchor" href="#updating-and-uninstalling" aria-label="Permalink to &quot;Updating and Uninstalling&quot;">​</a></h2><ul><li><strong>Updating</strong>: Run the newer installer. It replaces the program and the registration.</li><li><strong>Uninstalling</strong>: <ul><li>Windows: Use &quot;Uninstall Mug Typography MCP&quot; in the Start menu, or Settings &gt; Apps. This also removes the registration from the AI clients.</li><li>macOS: Open <code>MugTypographyMCP</code> and click <strong>Unregister all</strong> to remove the registration, then move <code>~/Applications/MugTypographyMCP.app</code> to the Trash.</li></ul></li></ul><h2 id="if-it-does-not-work" tabindex="-1">If It Does Not Work <a class="header-anchor" href="#if-it-does-not-work" aria-label="Permalink to &quot;If It Does Not Work&quot;">​</a></h2><ul><li><strong>The AI does not use Mug Typography&#39;s features</strong> — Restart the AI client or reload its MCP servers. <strong>Check the connection</strong> in the window also shows whether the AI can call it.</li><li><strong>The window shows &quot;Another copy&quot;</strong> — A copy you installed in another place is registered with an AI client. Press <strong>Register all</strong> to replace it with the current one.</li></ul>',19))])}const k=a(h,[["render",c]]);export{f as __pageData,k as default};
